contract InvMutTest {
    C c;
    bool private rejectEther;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount, bool reject) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(depAmount > 0, "deposit amount must be positive");
        require(address(this).balance >= depAmount, "not enough balance to deposit");

        c.deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        rejectEther = reject;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == reject);
    }

    receive() external payable {
        require(!rejectEther, "rejecting Ether");
    }
}

