pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;
    bool private rejectEther;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depAmount, bool reject) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depAmount > 0);
        vm.assume(address(this).balance >= depAmount);
        try c.deposit{value: depAmount}() {} catch { return; }
        rejectEther = reject;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == reject);
    }

    function testFuzz_run(uint256 depAmount, bool reject) public {
        _run(depAmount, reject);
    }

    receive() external payable {
        require(!rejectEther, "rejecting Ether");
    }
}
